/**
 * Time. One turn is one season.
 *
 * Why seasons rather than days: the events this game is about (raising troops,
 * a campaign, grain running out, a man dying of illness) are measured in
 * months, and a day-stepped clock would produce hundreds of empty turns between
 * the moments that matter. Four turns a year also makes the age arithmetic
 * exact, which matters because the whole point of this character is that he
 * spends twenty years not getting anywhere.
 *
 * The calendar is deliberately simplified: twelve months of thirty days. We are
 * simulating a story, not keeping an ephemeris, and an exact lunar calendar
 * would buy nothing a player can feel.
 */

/** Seasons, in order. Turn index within a year is `month` derived from these. */
export const SEASONS = ['春', '夏', '秋', '冬']

/** Month the season starts on (1-based, 30-day months). */
const SEASON_START_MONTH = [1, 4, 7, 10]

/** Turn index 0..3 -> month number. */
export function monthOfTurn(turn) {
  const index = ((turn % 4) + 4) % 4
  return SEASON_START_MONTH[index]
}

/** Turn index 0..3 -> season label. */
export function seasonOfTurn(turn) {
  const index = ((turn % 4) + 4) % 4
  return SEASONS[index]
}

/** Birth year, fixed by the sources. Used for every age calculation. */
export const BIRTH_YEAR = 161

/** Age in whole years at a given calendar year. */
export function ageAt(year) {
  return Math.max(0, Math.trunc(year) - BIRTH_YEAR)
}

/**
 * Advance the clock by `turns` seasons.
 *
 * Returns a NEW clock; never mutates the input. The age is recomputed from the
 * year rather than incremented, so a save edited by hand or a migrated old save
 * still reports a correct age.
 */
export function advance(clock, turns = 1) {
  const step = Math.max(0, Math.trunc(Number.isFinite(turns) ? turns : 1))
  const startTurn = Number.isFinite(clock?.turn) ? clock.turn : 0
  const startYear = Number.isFinite(clock?.year) ? clock.year : 184
  const total = startTurn + step
  const yearsPassed = Math.floor(total / 4)
  const year = startYear + yearsPassed
  const turn = ((total % 4) + 4) % 4
  return {
    year,
    month: monthOfTurn(turn),
    day: 1,
    turn,
    season: seasonOfTurn(turn),
    age: ageAt(year)
  }
}

/**
 * A human-readable date. Deliberately not a real 干支 cycle: getting the sexagenary
 * year right for every date is a research task with no gameplay payoff, and a
 * wrong one is worse than an honest "建安五年·春".
 */
export function formatDate(clock) {
  const year = Number.isFinite(clock?.year) ? clock.year : 184
  const season = clock?.season ?? seasonOfTurn(clock?.turn ?? 0)
  return `${year}年·${season}`
}

/** Reign-era label used in dialogue. Falls back to the plain year. */
export const ERA_STARTS = [
  { from: 184, name: '中平', base: 184 },
  { from: 190, name: '初平', base: 190 },
  { from: 194, name: '兴平', base: 194 },
  { from: 196, name: '建安', base: 196 }
]

export function eraOf(year) {
  let chosen = null
  for (const era of ERA_STARTS) {
    if (year >= era.from) {
      chosen = era
    }
  }
  if (chosen === null) {
    // Before 中平 there is no reign label worth inventing. Returning the empty
    // string lets the digest print the plain year once instead of "161年（161年）".
    return ''
  }
  const index = year - chosen.base + 1
  // 元年, not 一年: the first year of an era never takes a numeral.
  return index === 1 ? `${chosen.name}元年` : `${chosen.name}${toChineseNumeral(index)}年`
}

const DIGITS = ['零', '一', '二', '三', '四', '五', '六', '七', '八', '九']

/** Small helper for era ordinals (1..99 is all we need). */
export function toChineseNumeral(value) {
  const n = Math.trunc(value)
  if (!Number.isFinite(n) || n < 0) return '〇'
  if (n < 10) return DIGITS[n]
  if (n < 20) return `十${n % 10 === 0 ? '' : DIGITS[n % 10]}`
  if (n < 100) {
    const tens = Math.floor(n / 10)
    const ones = n % 10
    return `${DIGITS[tens]}十${ones === 0 ? '' : DIGITS[ones]}`
  }
  return String(n)
}

/**
 * How many seasons until the player reaches a given age. Used by the act table
 * to gate nodes on age rather than absolute year, so a run that drifts in time
 * still hits the right beats.
 */
export function seasonsUntilAge(clock, targetAge) {
  const currentAge = Number.isFinite(clock?.age) ? clock.age : ageAt(clock?.year ?? 184)
  const years = targetAge - currentAge
  return Math.max(0, years * 4)
}
